SELECT id, symbol, status, started_at, last_evidence_at, latest_signal_id, five_minute_decision, one_hour_decision, execution_source, recommended_position_percent, decision_code, LEFT(decision_explanation, 400) AS decision_explanation, executed_at, created_at, updated_at FROM crypto_ai.execution_opportunity WHERE (symbol='EGLDUSDT' AND (executed_at BETWEEN '2026-10-11 22:39:55' AND '2026-10-11 22:41:00' OR updated_at BETWEEN '2026-10-11 22:39:55' AND '2026-10-11 22:41:00')) OR (symbol='XRPUSDT' AND (executed_at BETWEEN '2026-10-12 02:34:55' AND '2026-10-12 02:36:00' OR updated_at BETWEEN '2026-10-12 02:34:55' AND '2026-10-12 02:36:00')) OR (symbol='SHIBUSDT' AND (executed_at BETWEEN '2026-10-12 06:35:55' AND '2026-10-12 06:37:00' OR updated_at BETWEEN '2026-10-12 06:35:55' AND '2026-10-12 06:37:00')) ORDER BY symbol, updated_at LIMIT 20;